INSERT INTO t_knowledge_doc (destination, doc_type, title, content, tags, source_name, source_url, sort_weight) VALUES
('成都', 'poi', '成都熊猫基地与市区玩法', '熊猫基地建议开园即到，上午熊猫更活跃，游览约 3 小时。市区宽窄巷子适合傍晚，春熙路与太古里适合晚上逛街。都江堰可安排半天到一天，动车往返方便。', '["熊猫","景点","亲子"]'::jsonb, '内置知识库（演示）', NULL, 100),
('成都', 'tip', '成都交通与饮食提示', '地铁覆盖主要景点，熊猫基地可乘地铁 3 号线转景区接驳。火锅微辣对外地人仍偏辣，可点鸳鸯锅。热门餐厅晚市排队久，建议错峰或提前取号。', '["交通","美食","避坑"]'::jsonb, '内置知识库（演示）', NULL, 90),
('大理', 'poi', '大理环洱海两日路线', '环洱海建议分两天：西线喜洲、海舌公园、双廊；东线小普陀、挖色、理想邦。骑行注意防晒与补水，环湖公路部分路段车流较大。', '["洱海","骑行","自然风光"]'::jsonb, '内置知识库（演示）', NULL, 100),
('大理', 'tip', '大理住宿与节奏', '古城适合晚上逛，喜洲或双廊住一晚能避开往返奔波。昼夜温差大，即使夏季也建议带薄外套。旺季海景房价格浮动明显，提前预订更稳。', '["住宿","气候","松弛"]'::jsonb, '内置知识库（演示）', NULL, 90),
('东京', 'poi', '东京赏樱与城市动线', '上野公园、千鸟渊、目黑川是三条经典樱花线，花期通常集中在 3 月下旬到 4 月上旬。浅草寺建议清晨前往，避开 9 点后的人流；镰仓可安排一日往返。', '["赏樱","人文","城市"]'::jsonb, '内置知识库（演示）', NULL, 100),
('东京', 'tip', '东京交通与预算提示', '市区以地铁和 JR 为主，建议使用交通 IC 卡。筑地场外市场适合早餐，但周日部分店铺休息。热门餐厅多需预约，便利店与定食店是控制预算的稳妥选择。', '["交通","美食","预算"]'::jsonb, '内置知识库（演示）', NULL, 90),
('西安', 'poi', '西安兵马俑与城墙路线', '兵马俑建议上午出发，先看一号坑再按顺序游览，全程约 3 小时。城墙可傍晚骑行，永宁门上下车方便。大唐不夜城适合晚上，回民街挑两三家即可，不必排网红长队。', '["历史","景点","夜游"]'::jsonb, '内置知识库（演示）', NULL, 100),
('西安', 'tip', '西安出行提醒', '兵马俑与市区距离较远，可乘地铁 9 号线转公交或选择正规一日游。夏季干热，冬季风大，城墙上骑行注意补水与防晒。', '["交通","气候","避坑"]'::jsonb, '内置知识库（演示）', NULL, 90),
('厦门', 'poi', '厦门环岛与沙坡尾', '环岛路适合骑行，黄厝到曾厝垵一段海景最好。沙坡尾和八市更能感受本地生活；鼓浪屿需提前买船票，旺季人流大，建议早班船。', '["海边","骑行","美食"]'::jsonb, '内置知识库（演示）', NULL, 100),
('厦门', 'tip', '厦门天气与住宿', '夏秋多台风，出发前关注天气与船班通知。住宿可选中山路或曾厝垵，前者交通方便，后者更近海边。海鲜排档先问价再点单。', '["天气","住宿","避坑"]'::jsonb, '内置知识库（演示）', NULL, 90),
('重庆', 'poi', '重庆立体城市玩法', '李子坝轻轨穿楼、鹅岭二厂、洪崖洞适合串成一条线，洪崖洞夜景人多，建议对岸或桥上观看。山城步道适合慢走，导航时注意上下层入口。', '["夜景","城市","步行"]'::jsonb, '内置知识库（演示）', NULL, 100),
('重庆', 'tip', '重庆交通与饮食', '轻轨比打车更稳，尤其过江与热门商圈。火锅默认牛油锅底，肠胃敏感可选清油或鸳鸯锅。夏季闷热，行程中留出午休时间。', '["交通","美食","气候"]'::jsonb, '内置知识库（演示）', NULL, 90),
('青海大环线', 'guide', '青海大环线节奏建议', '大环线全程较长，建议 6 到 8 天，西宁出发经青海湖、茶卡、大柴旦、敦煌、张掖返回。每天车程控制在 4 到 6 小时，高原路段避免夜间行车。', '["自驾","高原","自然风光"]'::jsonb, '内置知识库（演示）', NULL, 100),
('青海大环线', 'tip', '青海高原注意事项', '青海湖海拔约 3200 米，初到避免剧烈运动与饮酒。紫外线强，防晒和润唇用品必备。昼夜温差大，即使夏季也要带抓绒或薄羽绒。', '["高原","装备","气候"]'::jsonb, '内置知识库（演示）', NULL, 90),
('京都', 'poi', '京都寺庙与街区慢走', '清水寺建议清晨前往，二年坂三年坂随后逛。伏见稻荷大社可走到千本鸟居中段即返。岚山竹林与渡月桥适合半天，避开正午人流。', '["寺庙","人文","步行"]'::jsonb, '内置知识库（演示）', NULL, 100),
('京都', 'tip', '京都交通与礼仪', '市区公交比地铁覆盖更广，建议购买一日券。寺庙内注意安静与拍摄限制。樱花与红叶季住宿紧张，需提前数月预订。', '["交通","礼仪","住宿"]'::jsonb, '内置知识库（演示）', NULL, 90),
('三亚', 'poi', '三亚亲子海湾选择', '亚龙湾沙质细、适合亲子；海棠湾酒店新但离市区远；三亚湾看日落方便。蜈支洲岛水质好，旺季建议早班船并预留排队时间。', '["亲子","海边","度假"]'::jsonb, '内置知识库（演示）', NULL, 100),
('三亚', 'tip', '三亚出行提醒', '紫外线强，儿童需做好防晒与补水。海鲜市场加工先确认计价方式。春节与寒假是价格高峰，酒店与机票尽早锁定。', '["防晒","美食","避坑"]'::jsonb, '内置知识库（演示）', NULL, 90),
('长沙', 'poi', '长沙两日吃喝路线', '橘子洲与岳麓山可安排一天，岳麓书院适合慢逛。晚上五一广场、坡子街、文和友一线集中。茶颜悦色门店多，不必只排一家。', '["美食","城市","夜游"]'::jsonb, '内置知识库（演示）', NULL, 100),
('长沙', 'tip', '长沙排队与辣度', '热门餐饮排队时间长，建议错峰或线上取号。湘菜辣度可选，点单时主动说明微辣。夏季闷热，室内外温差大。', '["美食","避坑","气候"]'::jsonb, '内置知识库（演示）', NULL, 90),
('川西小环线', 'guide', '川西小环线路线建议', '经典小环线为成都—四姑娘山—丹巴—新都桥—康定—成都，建议 4 到 6 天。折多山与新都桥段海拔较高，行程应缓慢爬升，留出适应时间。', '["自驾","雪山","高原"]'::jsonb, '内置知识库（演示）', NULL, 100),
('川西小环线', 'tip', '川西自驾安全提示', '山路弯多，雨雪季注意路况与落石。高海拔地区避免剧烈运动，备好常用药与氧气。部分路段信号弱，提前下载离线地图。', '["自驾","安全","高原"]'::jsonb, '内置知识库（演示）', NULL, 90),
('青岛', 'poi', '青岛老城与海岸线', '栈桥、天主教堂、八大关适合步行串联；崂山安排一天，海边浴场夏季人多。啤酒博物馆可了解本地啤酒历史，晚上台东步行街觅食。', '["海边","人文","美食"]'::jsonb, '内置知识库（演示）', NULL, 100),
('青岛', 'tip', '青岛季节与海鲜', '夏季是旺季，海边紫外线强；秋冬海风大但人少。海鲜市场购买后找店加工，先确认加工费。', '["气候","海鲜","避坑"]'::jsonb, '内置知识库（演示）', NULL, 90),
('丽江', 'poi', '丽江与香格里拉路线', '丽江古城适合晚上，玉龙雪山需预留一天并提前预约索道。前往香格里拉沿途海拔上升，建议在丽江适应一晚再出发。', '["古城","雪山","高原"]'::jsonb, '内置知识库（演示）', NULL, 100),
('香格里拉', 'tip', '香格里拉高原提示', '海拔约 3300 米，初到避免洗澡后受凉与剧烈运动。普达措国家公园早晚温差大，带保暖外套。尊重当地宗教与拍摄习俗。', '["高原","装备","礼仪"]'::jsonb, '内置知识库（演示）', NULL, 90),
('首尔', 'poi', '首尔购物与城市漫步', '明洞适合一站式购物，弘大与圣水洞更适合小店与咖啡。景福宫可租韩服免门票，北村韩屋村注意居民区安静。', '["购物","城市","人文"]'::jsonb, '内置知识库（演示）', NULL, 100),
('首尔', 'tip', '首尔交通与消费', '地铁覆盖广，建议使用交通卡。热门餐厅可用排队机取号。退税需保留小票并在机场办理。', '["交通","购物","避坑"]'::jsonb, '内置知识库（演示）', NULL, 90),
('桂林阳朔', 'poi', '桂林阳朔山水路线', '漓江精华段可乘竹筏或游船，遇龙河比漓江更安静，适合骑行与漂流。阳朔西街晚上热闹，十里画廊适合白天骑行。', '["山水","骑行","自然风光"]'::jsonb, '内置知识库（演示）', NULL, 100),
('桂林阳朔', 'tip', '阳朔出行提醒', '雨季水位变化可能影响竹筏，出发前确认运营情况。骑行注意防晒与车辆检查。西街餐饮价格差异大，先看菜单。', '["天气","骑行","避坑"]'::jsonb, '内置知识库（演示）', NULL, 90);
